<?php
if (!defined('ABSPATH')) { exit; }
add_action('admin_menu', function(){ add_submenu_page('mhm-qc-admin','Quiz Admin','Quiz Admin','manage_options','mhm-qc-quiz-admin','qc_quiz_admin_page');});
function qc_quiz_admin_page(){ global $wpdb; if(isset($_POST['title'])&&check_admin_referer('qc_quiz_save')){$wpdb->insert($wpdb->prefix.'quran_quizzes',['title'=>sanitize_text_field($_POST['title']),'quiz_json'=>wp_kses_post($_POST['quiz_json']),'level'=>sanitize_text_field($_POST['level'])]); echo '<div class="updated"><p>Saved</p></div>';} if(isset($_GET['delete'])){$wpdb->delete($wpdb->prefix.'quran_quizzes',['id'=>absint($_GET['delete'])]);}
$rows=$wpdb->get_results("SELECT id,title,level FROM {$wpdb->prefix}quran_quizzes ORDER BY id DESC",ARRAY_A);
?><div class="wrap"><h1>Quiz Admin</h1><form method="post"><?php wp_nonce_field('qc_quiz_save'); ?><input name="title" placeholder="Quiz title" required><input name="level" value="beginner"><textarea name="quiz_json" required></textarea><button class="button button-primary">Save</button></form><table class="widefat"><tr><th>ID</th><th>Title</th><th>Level</th><th>Action</th></tr><?php foreach($rows as $r): ?><tr><td><?php echo esc_html((string)$r['id']); ?></td><td><?php echo esc_html($r['title']); ?></td><td><?php echo esc_html($r['level']); ?></td><td><a href="?page=mhm-qc-quiz-admin&delete=<?php echo esc_attr((string)$r['id']); ?>">Delete</a></td></tr><?php endforeach; ?></table></div><?php }
